const CONFIG = {
  SUPABASE_URL: 'https://tzkvbtozhsrlmcpbrstp.supabase.co',
  SUPABASE_ANON_KEY: 'ВСТАВЬ_SUPABASE_ANON_KEY',
};

function result(body, statusCode = 200) {
  return [{ json: { statusCode, ...body } }];
}

function cleanAnonKey(value) {
  return String(value || '')
    .trim()
    .replace(/^VITE_SUPABASE_ANON_KEY\s*=\s*/, '')
    .replace(/^['"]|['"]$/g, '')
    .trim();
}

function hasPlaceholder(value) {
  return !value || String(value).includes('ВСТАВЬ_');
}

function isUuid(value) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value || ''));
}

function getSupabaseError(error) {
  const rawBody = error?.response?.body || error?.body || null;
  let body = rawBody;
  if (typeof rawBody === 'string') {
    try { body = JSON.parse(rawBody); } catch { body = null; }
  }

  const rawMessage = String(body?.message || error?.message || 'Unknown error');
  const statusMatch = rawMessage.match(/\b([45]\d{2})\b/);
  const status = Number(
    error?.statusCode ||
    error?.response?.statusCode ||
    error?.httpCode ||
    body?.statusCode ||
    statusMatch?.[1] ||
    0
  );

  return {
    supabase_status: status || null,
    supabase_code: body?.code ? String(body.code).slice(0, 40) : null,
    supabase_message: rawMessage
      .replace(/[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}/g, '[token]')
      .slice(0, 300),
  };
}

const anonKey = cleanAnonKey(CONFIG.SUPABASE_ANON_KEY);
if (hasPlaceholder(anonKey)) {
  return result({ ready: false, error: 'n8n workflow is not configured: replace SUPABASE_ANON_KEY placeholder' }, 500);
}

const request = $input.first().json;
const headers = request.headers || {};
const authorization = headers.authorization || headers.Authorization || '';
const token = authorization.startsWith('Bearer ') ? authorization.slice(7).trim() : '';
if (!token) return result({ ready: false, error: 'Требуется авторизация' }, 401);

const body = request.body || {};
const userId = String(body.user_id || '').trim();
const message = String(body.message || '').trim();

if (!isUuid(userId)) {
  return result({ ready: false, error: 'Некорректный user_id' }, 400);
}
if (!message) {
  return result({ ready: false, error: 'Введите сообщение' }, 400);
}
if (message.length > 4000) {
  return result({ ready: false, error: 'Сообщение не должно превышать 4000 символов' }, 400);
}

let recipient;
try {
  recipient = await this.helpers.httpRequest({
    method: 'POST',
    url: `${CONFIG.SUPABASE_URL}/rest/v1/rpc/admin_get_max_recipient`,
    headers: {
      apikey: anonKey,
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: { p_user_id: userId },
    json: true,
  });
} catch (error) {
  const diagnostic = getSupabaseError(error);
  if (diagnostic.supabase_status === 401) {
    return result({ ready: false, error: 'Supabase отклонил сессию или anon key', diagnostic }, 401);
  }
  if (diagnostic.supabase_status === 403) {
    return result({ ready: false, error: 'Нет доступа к отправке сообщений', diagnostic }, 403);
  }
  if (diagnostic.supabase_status === 404) {
    return result({ ready: false, error: 'Supabase не нашел admin_get_max_recipient', diagnostic }, 502);
  }
  if (diagnostic.supabase_status === 400) {
    return result({ ready: false, error: 'Supabase вернул ошибку RPC', diagnostic }, 502);
  }
  return result({ ready: false, error: 'Не удалось проверить получателя в Supabase', diagnostic }, 502);
}

if (!recipient?.max_user_id) {
  return result({ ready: false, error: 'У пользователя нет MAX user_id' }, 404);
}

return result({
  ready: true,
  max_user_id: String(recipient.max_user_id),
  message,
}, 200);

const CONFIG = {
  MAX_BOT_TOKEN: 'ВСТАВЬ_MAX_BOT_TOKEN',
};

function result(body, statusCode = 200) {
  return [{ json: { statusCode, ...body } }];
}

function cleanToken(value) {
  return String(value || '')
    .trim()
    .replace(/^Authorization\s*:\s*/i, '')
    .replace(/^['"]|['"]$/g, '')
    .trim();
}

function getMaxError(error, botToken) {
  const rawBody = error?.response?.body || error?.body || null;
  let body = rawBody;
  if (typeof rawBody === 'string') {
    try { body = JSON.parse(rawBody); } catch { body = null; }
  }

  const rawMessage = String(body?.message || error?.message || 'Unknown error');
  const statusMatch = rawMessage.match(/\b([45]\d{2})\b/);
  const status = Number(
    error?.statusCode ||
    error?.response?.statusCode ||
    error?.httpCode ||
    body?.statusCode ||
    statusMatch?.[1] ||
    0
  );

  return {
    max_status: status || null,
    max_code: body?.code ? String(body.code).slice(0, 40) : null,
    max_message: rawMessage.split(botToken).join('[token]').slice(0, 300),
  };
}

const botToken = cleanToken(CONFIG.MAX_BOT_TOKEN);
if (!botToken || botToken.includes('ВСТАВЬ_')) {
  return result({ ok: false, error: 'n8n workflow is not configured: replace MAX_BOT_TOKEN placeholder' }, 500);
}

const input = $input.first().json;
const maxUserId = String(input.max_user_id || '').trim();
const message = String(input.message || '').trim();
if (!/^\d+$/.test(maxUserId)) {
  return result({ ok: false, error: 'Некорректный MAX user_id' }, 400);
}
if (!message || message.length > 4000) {
  return result({ ok: false, error: 'Некорректный текст сообщения' }, 400);
}

let response;
try {
  response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://platform-api2.max.ru/messages',
    qs: { user_id: maxUserId },
    headers: {
      Authorization: botToken,
      'Content-Type': 'application/json',
    },
    body: {
      text: message,
      notify: true,
    },
    json: true,
  });
} catch (error) {
  const diagnostic = getMaxError(error, botToken);
  if (diagnostic.max_status === 401) {
    return result({ ok: false, error: 'MAX отклонил токен бота', diagnostic }, 502);
  }
  if (diagnostic.max_status === 404) {
    return result({ ok: false, error: 'MAX не нашел пользователя или диалог', diagnostic }, 502);
  }
  if (diagnostic.max_status === 429) {
    return result({ ok: false, error: 'Превышен лимит отправки MAX', diagnostic }, 429);
  }
  return result({ ok: false, error: 'MAX не принял сообщение', diagnostic }, 502);
}

return result({
  ok: true,
  max_message_id: response?.body?.mid || response?.message?.body?.mid || response?.mid || null,
}, 200);
